package vn.edu.eaut.lab7.controller;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.edu.eaut.lab7.model.*;import vn.edu.eaut.lab7.repository.*;import java.io.*;
@WebServlet("/san-pham")public class SanPhamController extends HttpServlet{private final SanPhamRepository r=new SanPhamRepository();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String a=q.getParameter("action");if("new".equals(a)){q.getRequestDispatcher("/views/sanpham/form.jsp").forward(q,p);return;}if("edit".equals(a)||"detail".equals(a)){q.setAttribute("sp",r.findById(Integer.parseInt(q.getParameter("id"))));q.getRequestDispatcher("/views/sanpham/"+("edit".equals(a)?"form":"detail")+".jsp").forward(q,p);return;}if("delete".equals(a)){r.delete(Integer.parseInt(q.getParameter("id")));p.sendRedirect(q.getContextPath()+"/san-pham");return;}q.setAttribute("danhSach",r.search(q.getParameter("keyword")));q.getRequestDispatcher("/views/sanpham/list.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{int id=q.getParameter("id")==null||q.getParameter("id").isBlank()?0:Integer.parseInt(q.getParameter("id"));double g=Double.parseDouble(q.getParameter("gia"));int s=Integer.parseInt(q.getParameter("soLuong"));if(g<=0||s<0){p.sendRedirect(q.getContextPath()+"/san-pham");return;}SanPham x=new SanPham(id,q.getParameter("ma"),q.getParameter("ten"),q.getParameter("moTa"),g,s);if(id==0)r.add(x);else r.update(x);p.sendRedirect(q.getContextPath()+"/san-pham");}}
